using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace Formula81.XrmToolBox.Tools.ViewDriver
{
    [Export(typeof(IXrmToolBoxPlugin)),
        ExportMetadata("Name", ViewDriverPlugin.PluginName),
        ExportMetadata("Description", "Manage personal views the practical way: edit columns, filters and sorting, see the data and clone views"),
        // 32x32 pixels
        ExportMetadata("SmallImageBase64", ""),
        // 80x80 pixels
        ExportMetadata("BigImageBase64", ""),
        ExportMetadata("BackgroundColor", "#FF8000"),
        ExportMetadata("PrimaryFontColor", "White"),
        ExportMetadata("SecondaryFontColor", "Black")]
    public class ViewDriverPlugin : PluginBase, IPayPalPlugin
    {
        internal const string PluginName = "View Driver";
        internal const string PayPalEmailAccount = "formulaeightyone@gmail.com";
        internal const string PayPalDonationDescription = "Formula 81 Donation";

        public string DonationDescription => PayPalDonationDescription;
        public string EmailAccount => PayPalEmailAccount;

        public override IXrmToolBoxPluginControl GetControl()
        {
            return new ViewDriverPluginControl();
        }
    }
}
